parameters.jsCode:
const ev = $json.event || $json;
const approvalChannel = $env.SLACK_APPROVAL_CHANNEL_ID;
const approver = $env.SLACK_APPROVER_USER_ID;
const type = ev.type || $json.type || '';
const user = ev.user || $json.user || '';
const channel = ev.channel || ev.item?.channel || $json.channel || '';

if (channel !== approvalChannel) return [];
if (user !== approver) return [];

if (type === 'reaction_added') {
  const reaction = ev.reaction || $json.reaction || '';
  const targetTs = (ev.item || {}).ts || $json.item?.ts;
  if (!targetTs) return [];
  if (reaction === 'white_check_mark' || reaction === '+1' || reaction === 'heavy_check_mark') {
    return [{ json: { route: 'send_draft_as_is', target_ts: targetTs, channel } }];
  }
  if (reaction === 'x' || reaction === 'no_entry_sign') {
    return [{ json: { route: 'mark_manual', target_ts: targetTs, channel } }];
  }
  return [];
}
if (type === 'message') {
  // Edited reply must be in a thread under the approval message
  const threadTs = ev.thread_ts || $json.thread_ts;
  const subtype = ev.subtype || $json.subtype || '';
  if (subtype) return []; // ignore bot_message, message_changed, etc.
  if (!threadTs) return []; // top-level messages, ignore
  const text = ev.text || $json.text || '';
  if (!text.trim()) return [];
  return [{ json: { route: 'send_edited', target_ts: threadTs, channel, edited_text: text } }];
}
return [];

const msgs = $json.messages || [];
const lookup = $('Build History Lookup').item.json;
if (!msgs.length) return [];
const msg = msgs[0];
const meta = msg.metadata || {};
if (meta.event_type !== 'outreach_approval') return [];
const payload = meta.event_payload || {};
return [{ json: {
  route: lookup._route,
  edited_text: lookup._edited_text || '',
  gmail_thread_id: payload.gmail_thread_id,
  gmail_message_id: payload.gmail_message_id,
  lead_email: payload.lead_email,
  sender_email: payload.sender_email,
  sender_name: payload.sender_name,
  leads_item_id: payload.leads_item_id,
  subject: payload.subject,
  claude_draft: payload.claude_draft,
  channel: lookup.channel,
  approval_ts: lookup.latest
}}];

